// Invented addresses, Gmail's real multipart/full-message shape; no mailbox data.
const part = (mimeType, text) => ({mimeType, body:{size:Buffer.byteLength(text), data:Buffer.from(text).toString('base64url')}});
export function gmailMessage(id, text, html, from='Teresa Martin <teresa@example.test>') {
 return {id,threadId:`thread-${id}`,internalDate:'1793185200000',labelIds:['INBOX','UNREAD'],snippet:text.replace(/\s+/g,' ').slice(0,150),payload:{mimeType:'multipart/alternative',headers:Object.entries({From:from,To:'Joe <joe@example.test>',Subject:'Basement project details','Message-ID':`<${id}@mail.test>`}).map(([name,value])=>({name,value})),parts:[...(text?[part('text/plain',text)]:[]),part('text/html',html)]}};
}
